namespace sv_87ec91808ff3405e8dfc10b26105ee8f.Services;

public enum Theme
{
    Light,
    Dark,
    System
}

/// <summary>
/// Scoped service — one instance per interactive circuit.
/// Static SSR requests get a throwaway instance, so theme-consuming
/// components must use @rendermode InteractiveServer to share state.
/// </summary>
public sealed class ThemeService : IDisposable
{
    private Theme _theme = Theme.System;
    private string _accentColor = "#0d6efd";

    public Theme CurrentTheme
    {
        get => _theme;
        set
        {
            if (_theme == value) return;
            _theme = value;
            NotifyChanged();
        }
    }

    public string AccentColor
    {
        get => _accentColor;
        set
        {
            if (_accentColor == value) return;
            _accentColor = value;
            NotifyChanged();
        }
    }

    /// <summary>
    /// Raised whenever theme or accent color changes.
    /// Subscribers must call StateHasChanged() in their handler.
    /// </summary>
    public event Action? OnChange;

    private void NotifyChanged() => OnChange?.Invoke();

    public void Dispose() => OnChange = null;
}

@* Interactive island — lives inside the static MainLayout but runs on the circuit. *@
@rendermode InteractiveServer
@inject ThemeService ThemeService
@implements IDisposable

<span class="badge rounded-pill"
      style="background-color: @ThemeService.AccentColor; color: white;">
    @ThemeService.CurrentTheme
</span>

@code {
    protected override void OnInitialized()
    {
        ThemeService.OnChange += StateHasChanged;
    }

    public void Dispose()
    {
        ThemeService.OnChange -= StateHasChanged;
    }
}

@rendermode InteractiveServer
@inject ThemeService ThemeService
@implements IDisposable

<button class="btn btn-sm btn-outline-secondary" @onclick="CycleTheme"
        title="Toggle theme">
    @Icon
</button>

@code {
    private string Icon => ThemeService.CurrentTheme switch
    {
        Theme.Light  => "☀️",
        Theme.Dark   => "🌙",
        _            => "💻"
    };

    protected override void OnInitialized()
    {
        ThemeService.OnChange += StateHasChanged;
    }

    private void CycleTheme()
    {
        ThemeService.CurrentTheme = ThemeService.CurrentTheme switch
        {
            Theme.Light  => Theme.Dark,
            Theme.Dark   => Theme.System,
            _            => Theme.Light
        };
    }

    public void Dispose()
    {
        ThemeService.OnChange -= StateHasChanged;
    }
}

@page "/settings"
@rendermode InteractiveServer
@inject ThemeService ThemeService
@implements IDisposable

<PageTitle>Settings</PageTitle>

<h1>User Preferences</h1>

<div class="mb-3">
    <label class="form-label fw-bold">Theme</label>
    <div class="btn-group d-block" role="group">
        @foreach (var t in Enum.GetValues<Theme>())
        {
            var theme = t;
            <button class="btn @(ThemeService.CurrentTheme == theme ? "btn-primary" : "btn-outline-primary")"
                    @onclick="() => ThemeService.CurrentTheme = theme">
                @theme
            </button>
        }
    </div>
</div>

<div class="mb-3">
    <label class="form-label fw-bold">Accent Color</label>
    <input type="color" class="form-control form-control-color"
           value="@ThemeService.AccentColor"
           @onchange="OnColorChanged" />
</div>

<p class="text-muted">
    Changes apply instantly across every component in your session.
</p>

@code {
    protected override void OnInitialized()
    {
        ThemeService.OnChange += StateHasChanged;
    }

    private void OnColorChanged(ChangeEventArgs e)
    {
        ThemeService.AccentColor = e.Value?.ToString() ?? "#0d6efd";
    }

    public void Dispose()
    {
        ThemeService.OnChange -= StateHasChanged;
    }
}

